// Заглушка, созданная оркестратором. Реализацию пишет агент-разработчик.
import type { GameModule } from '../../../platform/sdk/types.ts';

const notImplemented = (): never => {
  throw new Error('NOT_IMPLEMENTED');
};

/** Заглушка игры coin: все методы бросают NOT_IMPLEMENTED. */
const game: GameModule = {
  id: 'coin',
  validateParams: notImplemented,
  start: notImplemented,
  action: notImplemented,
  publicView: notImplemented,
};

export default game;
<!doctype html>
<meta charset="utf-8">
<title>Монетка</title>
<p>NOT_IMPLEMENTED</p>
/**
 * Контракт между платформой и играми. Имена фиксированы: на них опираются все игры.
 * Игра импортирует из платформы только `platform/sdk/*`.
 */

/**
 * Генератор случайных чисел. `next()` возвращает число в [0, 1). Передаётся игре платформой.
 * На каждый вызов `start`/`action` игра получает отдельный замороженный объект; сохранять его между вызовами нельзя.
 */
export interface Rng {
  next(): number;
}

/**
 * Результат шага игры.
 * - `continue` — раунд продолжается, нужен следующий ход;
 * - `finished` — раунд окончен, `payout` — полная сумма к зачислению (0 при проигрыше).
 */
export type Step<S> =
  | { status: 'continue'; state: S }
  | { status: 'finished'; state: S; payout: number };

/**
 * Серверный модуль игры. Платформа вызывает его внутри раунда: списывает ставку до `start`
 * и зачисляет `payout` после шага со статусом `finished`. Игра не знает о кошельке и балансе.
 *
 * Состояние `S` и параметры `P` должны сериализоваться в JSON: платформа хранит их на диске.
 *
 * Порядок внутри `start`/`action`: сначала проверить `action` (бросить `INVALID_ACTION`) и всё, что может упасть,
 * и только потом обращаться к `rng`. После первого `rng.next()` исключения запрещены, а шаг должен быть корректным:
 * иначе повтор хода давал бы новый исход. Если игра всё же упала после `rng.next()`, платформа не возвращает
 * ставку и не даёт повторить ход: раунд блокируется для ручного разбора, клиент получает `INTERNAL_ERROR`.
 * Если игра упала в `start` до обращения к `rng`, раунд аннулируется, ставка возвращается.
 *
 * Серверный модуль работает в процессе ядра. Кроме `platform/sdk/*`, ему запрещены `process`, `globalThis`,
 * `require`, динамический `import()`, `fetch`, `eval`/`Function` и модули `node:*`: игра — чистая функция от
 * `ctx` и состояния.
 */
export interface GameModule<P = any, S = any, A = any> {
  /** Идентификатор игры, совпадает с `id` в `manifest.json`. */
  id: string;
  /** Проверяет и нормализует параметры раунда. Бросает `GameError('INVALID_PARAMS')`. */
  validateParams(params: unknown): P;
  /** Начинает раунд (ставка уже списана). */
  start(ctx: { bet: number; params: P; rng: Rng }): Step<S>;
  /** Ход игрока. Бросает `GameError('INVALID_ACTION')` на недопустимое действие. */
  action(ctx: { bet: number; params: P; state: S; action: A; rng: Rng }): Step<S>;
  /** Что можно показать клиенту. До конца раунда (`finished = false`) скрытое не раскрывается. */
  publicView(state: S, finished: boolean): unknown;
}

/** Ошибка игры с кодом (`INVALID_PARAMS`, `INVALID_ACTION`). Платформа передаёт код клиенту. */
export class GameError extends Error {
  /** Код ошибки. */
  code: string;

  /**
   * @param code код ошибки, например `INVALID_PARAMS`
   * @param message необязательное пояснение для игрока
   */
  constructor(code: string, message?: string) {
    super(message ?? code);
    this.name = 'GameError';
    this.code = code;
  }
}
// Контракт серверного модуля «Монетки» (games/coin/spec.md, SC-10; platform/sdk/types.ts).
// Проверяются только публичные методы GameModule и их результат, без опоры на внутреннее устройство.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import game from '../server/index.ts';
import { GameError } from '../../../platform/sdk/types.ts';

/** rng, который отдаёт заданные числа и бросает, когда они кончились; считает вызовы. */
function countingRng(values: number[]) {
  let calls = 0;
  const rng = {
    next(): number {
      calls += 1;
      if (calls > values.length) throw new Error('rng: лишний вызов');
      return values[calls - 1] as number;
    },
  };
  return { rng, calls: () => calls };
}

function gameErrorCode(fn: () => unknown): string {
  try {
    const v = fn();
    throw new Error(`ожидалась GameError, а вызов вернул ${JSON.stringify(v)}`);
  } catch (e: any) {
    expect(e).toBeInstanceOf(GameError);
    return e.code;
  }
}

describe('Монетка: контракт модуля игры', () => {
  beforeEach(() => {
    vi.spyOn(Math, 'random').mockImplementation(() => {
      throw new Error('Math.random запрещён в игре');
    });
  });
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('SC-10: id и validateParams нормализуют параметры до { side }', () => {
    expect(game.id).toBe('coin');
    expect(game.validateParams({ side: 'tails', x: 1 })).toEqual({ side: 'tails' });
    expect(game.validateParams({ side: 'heads' })).toEqual({ side: 'heads' });
  });

  it('SC-10: validateParams бросает GameError INVALID_PARAMS на неверные параметры', () => {
    for (const p of [{ side: 'edge' }, { side: 'HEADS' }, { side: 1 }, {}, null, undefined, 'heads', ['heads'], 42]) {
      expect(gameErrorCode(() => game.validateParams(p)), `params = ${JSON.stringify(p)}`).toBe('INVALID_PARAMS');
    }
  });

  it('SC-10: start закрывает раунд одним вызовом rng, состояние сериализуемо, publicView = { side, outcome, win }', () => {
    const { rng, calls } = countingRng([0.75]);
    const step: any = game.start({ bet: 4, params: { side: 'tails' }, rng });
    expect(calls()).toBe(1);
    expect(step.status).toBe('finished');
    expect(step.state).toEqual({ side: 'tails', outcome: 'tails', win: true });
    expect(step.payout).toBeCloseTo(7.84, 9);
    expect(JSON.parse(JSON.stringify(step.state))).toEqual(step.state);
    expect(game.publicView(step.state, true)).toEqual({ side: 'tails', outcome: 'tails', win: true });
  });

  it('SC-10: start при несовпадении стороны даёт payout 0 и win: false', () => {
    const { rng, calls } = countingRng([0.75]);
    const step: any = game.start({ bet: 4, params: { side: 'heads' }, rng });
    expect(calls()).toBe(1);
    expect(step.status).toBe('finished');
    expect(step.payout).toBe(0);
    expect(step.state).toEqual({ side: 'heads', outcome: 'tails', win: false });
    expect(game.publicView(step.state, true)).toEqual({ side: 'heads', outcome: 'tails', win: false });

    const low = countingRng([0.2]);
    const s2: any = game.start({ bet: 4, params: { side: 'heads' }, rng: low.rng });
    expect(low.calls()).toBe(1);
    expect(s2.state).toEqual({ side: 'heads', outcome: 'heads', win: true });
    expect(s2.payout).toBeCloseTo(7.84, 9);
  });

  it('SC-10: action бросает GameError INVALID_ACTION, не обращаясь к rng', () => {
    const first = countingRng([0.75]);
    const params = { side: 'tails' };
    const step: any = game.start({ bet: 4, params, rng: first.rng });
    const { rng, calls } = countingRng([0.1]);
    expect(gameErrorCode(() => game.action({ bet: 4, params, state: step.state, action: 'flip', rng }))).toBe('INVALID_ACTION');
    expect(calls()).toBe(0);
  });
});
// Приёмочные тесты «Монетки» через тестовую платформу (games/coin/spec.md, SC-1…SC-9).
// Поведение проверяется снаружи: ответы startRound/open/action, баланс, журнал транзакций, коды ошибок.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import game from '../server/index.ts';
import { createTestPlatform, fixedRng } from '../../../platform/testkit/index.ts';

/** Код ошибки, которую бросает fn; если fn не бросила — тест падает. */
function codeOf(fn: () => unknown): string {
  try {
    const v = fn();
    throw new Error(`ожидалась ошибка, а вызов вернул ${JSON.stringify(v)}`);
  } catch (e: any) {
    if (e instanceof Error && e.message.startsWith('ожидалась ошибка')) throw e;
    return e?.code;
  }
}

function platform(rng: number[], startBalance = 100) {
  return createTestPlatform({ games: [game], rng: fixedRng(rng), startBalance });
}

describe('Монетка: раунды через платформу', () => {
  beforeEach(() => {
    // Исход определяется только переданным rng (spec: «Math.random не используется»).
    vi.spyOn(Math, 'random').mockImplementation(() => {
      throw new Error('Math.random запрещён в игре');
    });
  });
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('SC-1: выигрыш на орле — выплата bet × 1.96, раунд закрыт сразу', () => {
    const p = platform([0.3]);
    const r = p.startRound('coin', 1, { side: 'heads' });
    expect(r.gameId).toBe('coin');
    expect(r.status).toBe('closed');
    expect(r.bet).toBe(1);
    expect(r.payout).toBe(1.96);
    expect(r.balance).toBe(100.96);
    expect(r.view).toEqual({ side: 'heads', outcome: 'heads', win: true });
    expect(p.balance()).toBe(100.96);
    const txs = p.transactions();
    expect(txs).toHaveLength(2);
    expect(txs[0]).toMatchObject({ type: 'bet', roundId: r.roundId, amount: 1, balanceAfter: 99 });
    expect(txs[1]).toMatchObject({ type: 'payout', roundId: r.roundId, amount: 1.96, balanceAfter: 100.96 });
  });

  it('SC-2: выигрыш на решке при rng ровно 0.5 и максимальной ставке 10', () => {
    const p = platform([0.5]);
    const r = p.startRound('coin', 10, { side: 'tails' });
    expect(r.status).toBe('closed');
    expect(r.bet).toBe(10);
    expect(r.payout).toBe(19.6);
    expect(r.balance).toBe(109.6);
    expect(r.view).toEqual({ side: 'tails', outcome: 'tails', win: true });
    expect(p.balance()).toBe(109.6);
    const txs = p.transactions();
    expect(txs).toHaveLength(2);
    expect(txs[0]).toMatchObject({ type: 'bet', amount: 10, balanceAfter: 90 });
    expect(txs[1]).toMatchObject({ type: 'payout', amount: 19.6, balanceAfter: 109.6 });
  });

  it('SC-3: проигрыш — выплата 0, ставка потеряна, раунд закрыт выплатой 0', () => {
    const p = platform([0.7]);
    const r = p.startRound('coin', 5, { side: 'heads' });
    expect(r.status).toBe('closed');
    expect(r.bet).toBe(5);
    expect(r.payout).toBe(0);
    expect(r.balance).toBe(95);
    expect(r.view).toEqual({ side: 'heads', outcome: 'tails', win: false });
    expect(p.balance()).toBe(95);
    const txs = p.transactions();
    expect(txs).toHaveLength(2);
    expect(txs[0]).toMatchObject({ type: 'bet', amount: 5, balanceAfter: 95 });
    expect(txs[1]).toMatchObject({ type: 'payout', amount: 0, balanceAfter: 95 });
  });

  it('SC-4: проигрыш у границы — rng 0.4999 даёт орла, ставка на решку проигрывает', () => {
    const p = platform([0.4999]);
    const r = p.startRound('coin', 2, { side: 'tails' });
    expect(r.status).toBe('closed');
    expect(r.view).toEqual({ side: 'tails', outcome: 'heads', win: false });
    expect(r.payout).toBe(0);
    expect(r.balance).toBe(98);
    expect(p.balance()).toBe(98);
    expect(p.transactions().map((t) => [t.type, t.amount, t.balanceAfter])).toEqual([
      ['bet', 2, 98],
      ['payout', 0, 98],
    ]);
  });

  it('SC-4: граница с другой стороны — rng 0.4999 при ставке на орла выигрывает', () => {
    const p = platform([0.4999]);
    const r = p.startRound('coin', 2, { side: 'heads' });
    expect(r.view).toEqual({ side: 'heads', outcome: 'heads', win: true });
    expect(r.payout).toBe(3.92);
    expect(r.balance).toBe(101.92);
  });

  it('SC-5: выплата округляется до центов — 3.33 × 1.96 = 6.5268 → 6.53', () => {
    const p = platform([0]);
    const r = p.startRound('coin', 3.33, { side: 'heads' });
    expect(r.status).toBe('closed');
    expect(r.bet).toBe(3.33);
    expect(r.view).toEqual({ side: 'heads', outcome: 'heads', win: true });
    expect(r.payout).toBe(6.53);
    expect(r.balance).toBe(103.2);
    expect(p.balance()).toBe(103.2);
    expect(p.transactions().map((t) => [t.type, t.amount, t.balanceAfter])).toEqual([
      ['bet', 3.33, 96.67],
      ['payout', 6.53, 103.2],
    ]);
  });

  it('SC-6: неверные параметры отклоняются до списания и не расходуют rng', () => {
    const p = platform([0.3]);
    const bad: unknown[] = [{ side: 'edge' }, { side: 'HEADS' }, { side: 1 }, {}, null, 'heads', ['heads'], { side: 'tails ' }];
    for (const params of bad) {
      expect(codeOf(() => p.startRound('coin', 1, params)), `params = ${JSON.stringify(params)}`).toBe('INVALID_PARAMS');
      expect(p.transactions()).toEqual([]);
      expect(p.balance()).toBe(100);
    }
    expect(p.open('coin').activeRound).toBeNull();

    // rng не тронут: единственное число 0.3 достаётся следующему корректному раунду.
    const r = p.startRound('coin', 1, { side: 'heads', extra: 42 });
    expect(r.status).toBe('closed');
    expect(r.payout).toBe(1.96);
    expect(r.balance).toBe(100.96);
    expect(r.view).toEqual({ side: 'heads', outcome: 'heads', win: true });
    expect(r.view).not.toHaveProperty('extra');
    expect(p.transactions()).toHaveLength(2);
  });

  it('SC-7: ставка вне лимитов отклоняется до списания', () => {
    const p = platform([0.3, 0.3]);
    expect(codeOf(() => p.startRound('coin', 0.5, { side: 'heads' }))).toBe('BET_OUT_OF_LIMITS');
    expect(codeOf(() => p.startRound('coin', 10.01, { side: 'heads' }))).toBe('BET_OUT_OF_LIMITS');
    expect(p.transactions()).toEqual([]);
    expect(p.balance()).toBe(100);
  });

  it('SC-8: недостаточно средств — ставка не списана, раунд не создан', () => {
    const p = platform([0.3], 5);
    expect(codeOf(() => p.startRound('coin', 6, { side: 'heads' }))).toBe('INSUFFICIENT_FUNDS');
    expect(p.transactions()).toEqual([]);
    expect(p.balance()).toBe(5);
    const o = p.open('coin');
    expect(o.activeRound).toBeNull();
    expect(o.balance).toBe(5);

    // rng не потрачен: следующий доступный по деньгам раунд получает 0.3.
    const r = p.startRound('coin', 5, { side: 'heads' });
    expect(r.payout).toBe(9.8);
    expect(r.balance).toBe(9.8);
  });

  it('SC-9: серия бросков — каждый раунд закрыт, action даёт ROUND_CLOSED, один rng на раунд', () => {
    const p = platform([0.1, 0.9]);
    const r1 = p.startRound('coin', 2, { side: 'heads' });
    expect(r1.status).toBe('closed');
    expect(r1.view).toEqual({ side: 'heads', outcome: 'heads', win: true });
    expect(r1.payout).toBe(3.92);
    expect(r1.balance).toBe(101.92);
    expect(p.open('coin').activeRound).toBeNull();

    expect(codeOf(() => p.action(r1.roundId, 'flip'))).toBe('ROUND_CLOSED');
    expect(p.balance()).toBe(101.92);
    expect(p.transactions()).toHaveLength(2);

    const r2 = p.startRound('coin', 2, { side: 'heads' });
    expect(r2.roundId).not.toBe(r1.roundId);
    expect(r2.status).toBe('closed');
    expect(r2.view).toEqual({ side: 'heads', outcome: 'tails', win: false });
    expect(r2.payout).toBe(0);
    expect(r2.balance).toBe(99.92);

    const o = p.open('coin');
    expect(o).toMatchObject({ gameId: 'coin', limits: { min: 1, max: 10 }, balance: 99.92, activeRound: null });
    expect(o.activeRound).toBeNull();
    expect(p.transactions().map((t) => [t.type, t.amount, t.balanceAfter])).toEqual([
      ['bet', 2, 98],
      ['payout', 3.92, 101.92],
      ['bet', 2, 99.92],
      ['payout', 0, 99.92],
    ]);
  });
});
// @vitest-environment happy-dom
// Интерфейс «Монетки» (games/coin/spec.md, SC-11): ui/index.html с подменённым window.PlatformSDK.
// Внешний /sdk.js не загружается; инлайновые скрипты страницы выполняются в глобальной области, как обычный <script>.
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it, vi } from 'vitest';

// Строка import.meta.url, а не new URL(): в happy-dom глобальный URL принадлежит окну, а не Node.
const HTML_PATH = resolve(dirname(fileURLToPath(import.meta.url)), '../ui/index.html');

/** Ждёт выполнения условия, прокручивая очередь задач. */
async function waitFor(cond: () => boolean, what: string, timeoutMs = 3000): Promise<void> {
  const started = Date.now();
  while (!cond()) {
    if (Date.now() - started > timeoutMs) throw new Error(`не дождались: ${what}`);
    await new Promise((r) => setTimeout(r, 5));
  }
}

const $ = (id: string): HTMLElement => {
  const el = document.querySelector(`[data-testid="${id}"]`) as HTMLElement | null;
  if (!el) throw new Error(`нет элемента data-testid="${id}"`);
  return el;
};

/** Первое число в тексте элемента (запятая как десятичный разделитель допускается). */
const numberIn = (id: string): number => {
  const m = ($(id).textContent ?? '').replace(/\s/g, '').replace(',', '.').match(/-?\d+(\.\d+)?/);
  return m ? Number(m[0]) : NaN;
};

const isDisabled = (el: HTMLElement): boolean =>
  (el as HTMLButtonElement).disabled === true || el.getAttribute('aria-disabled') === 'true';

function deferred<T>() {
  let resolve!: (v: T) => void;
  let reject!: (e: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

/** «Открывает» страницу: разметка без <script>, затем подмена SDK, затем инлайновые скрипты. */
function loadPage(sdk: unknown): void {
  const html = readFileSync(HTML_PATH, 'utf8');
  const scripts: string[] = [];
  const stripped = html.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi, (_m, attrs: string, code: string) => {
    if (!/\bsrc\s*=/.test(attrs) && code.trim()) scripts.push(code);
    return '';
  });
  const doc = new DOMParser().parseFromString(stripped, 'text/html');
  for (const a of Array.from(doc.documentElement.attributes)) document.documentElement.setAttribute(a.name, a.value);
  for (const a of Array.from(doc.body.attributes)) document.body.setAttribute(a.name, a.value);
  document.head.innerHTML = doc.head.innerHTML;
  document.body.innerHTML = doc.body.innerHTML;

  const g = globalThis as any;
  g.window.PlatformSDK = sdk;
  g.PlatformSDK = sdk;
  const indirectEval: (code: string) => unknown = g.eval;
  for (const code of scripts) indirectEval(code);
  document.dispatchEvent(new g.Event('DOMContentLoaded'));
  g.window.dispatchEvent(new g.Event('load'));
}

describe('Монетка: интерфейс', () => {
  it('SC-11: idle → playing → won, затем отказ платформы показывается без смены баланса', async () => {
    const pending = deferred<any>();
    const sdk = {
      open: vi.fn(async () => ({ gameId: 'coin', balance: 100, limits: { min: 1, max: 10 }, activeRound: null })),
      startRound: vi.fn((_bet: unknown, _params: unknown) => pending.promise),
      action: vi.fn(async () => {
        throw { code: 'ROUND_NOT_FOUND', message: 'нет раунда' };
      }),
    };
    loadPage(sdk);

    // Загрузка: idle, баланс из open(), ставка по умолчанию 1, выбран орёл.
    await waitFor(() => sdk.open.mock.calls.length > 0 && numberIn('balance') === 100, 'баланс 100 после open()');
    expect($('game').getAttribute('data-state')).toBe('idle');
    expect(Number(($('bet-input') as HTMLInputElement).value)).toBe(1);
    expect($('side-heads').getAttribute('aria-pressed')).toBe('true');
    expect($('side-tails').getAttribute('aria-pressed')).not.toBe('true');

    // Выбор решки.
    $('side-tails').click();
    expect($('side-tails').getAttribute('aria-pressed')).toBe('true');
    expect($('side-heads').getAttribute('aria-pressed')).not.toBe('true');

    // Бросок: пока запрос в пути — playing, кнопка заблокирована.
    $('play').click();
    await waitFor(() => sdk.startRound.mock.calls.length === 1, 'вызов startRound');
    expect(sdk.startRound).toHaveBeenCalledWith(1, { side: 'tails' });
    await waitFor(() => $('game').getAttribute('data-state') === 'playing', 'data-state=playing');
    expect(isDisabled($('play'))).toBe(true);
    // Пока ответа нет, исход и выплата не показаны.
    expect($('outcome').textContent ?? '').not.toMatch(/Решка|Орёл/);

    pending.resolve({
      roundId: 'round-1',
      gameId: 'coin',
      bet: 1,
      status: 'closed',
      payout: 1.96,
      balance: 100.96,
      view: { side: 'tails', outcome: 'tails', win: true },
    });
